 T(("TỶ TRỌNG", "QUYẾT ĐỊNH VẾT THƯƠNG"), "Điểm sai chỉ là một nửa. Nửa còn lại là tỷ trọng. Ví dụ, anh chị chấp nhận mỗi lệnh sai chỉ làm danh mục mất tối đa 1%. Nếu điểm sai theo giá cách giá mua 10%, tỷ trọng tối đa cho mã đó là 10% danh mục. Nếu điểm sai cách 20%, tỷ trọng tối đa còn 5%. Cách tính này đảo ngược thói quen phổ biến: chọn tỷ trọng theo mức độ thích một cổ phiếu. Ở đây, tỷ trọng được quyết định bởi khoảng cách tới điểm sai.", "balance scale weights", "Tỷ trọng quyết định vết thương", True, k='cards', cards=[('Rủi ro mỗi lệnh', '1%', 'danh mục'), ('Điểm sai −10%', 'tối đa 10%', 'tỷ trọng'), ('Điểm sai −20%', 'tối đa 5%', 'tỷ trọng')]),
 T(("MƯỜI LỆNH SAI", "VẪN CÒN VỐN"), "Với quy tắc mỗi lệnh sai mất 1% danh mục, mười lệnh sai liên tiếp làm danh mục giảm khoảng 9,6%, vì mỗi lần mất 1% của phần còn lại. Đó là một giai đoạn khó chịu, nhưng vẫn gỡ lại được. Ngược lại, nếu mỗi lệnh sai mất 10% danh mục, ba lệnh sai liên tiếp đã làm mất khoảng 27%, cần lãi khoảng 37% mới hòa. Người đầu tư lâu năm không phải người chưa bao giờ sai, mà là người mà mỗi lần sai đều nhỏ.", "survival compass", "Mười lệnh sai vẫn còn vốn", k='bignum', value=-9.6, fmt='{:,.1f}', unit='%', top='10 LỆNH SAI, MỖI LỆNH −1%', sub='danh mục vẫn còn hơn 90%', col=GOLD),
 T(("VÍ DỤ", "BẰNG SỐ"), "Một ví dụ cụ thể bằng số. Danh mục 500 triệu đồng, quy tắc mỗi lệnh sai mất tối đa 1%, tức 5 triệu đồng. Anh chị muốn mua một cổ phiếu giá 50 nghìn đồng, và điểm sai theo giá nằm ở 45 nghìn đồng, dưới đáy gần nhất. Khoảng cách tới điểm sai là 5 nghìn đồng mỗi cổ phiếu, tức 10%. Số cổ phiếu tối đa bằng 5 triệu chia cho 5 nghìn, tức 1.000 cổ phiếu, tương đương 50 triệu đồng, đúng 10% danh mục. Nếu cổ phiếu chạm điểm sai, anh chị mất khoảng 5 triệu đồng cộng phí giao dịch, và vẫn còn 99% danh mục để làm lệnh tiếp theo. Nếu cổ phiếu đúng như kỳ vọng, phần lãi không bị giới hạn bởi quy tắc này.", "calculator notebook", "Ví dụ bằng số", True, k='cards', cards=[('Danh mục', '500 triệu', ''), ('Rủi ro 1 lệnh', '5 triệu', '1%'), ('Mua 50 – sai 45', '1.000 cổ phiếu', '≈ 10% danh mục')]),
 T(("VÌ SAO KHÓ", "LÀM THEO"), "Vì sao biết mà vẫn khó làm? Vì cắt lỗ là thừa nhận mình sai, và não bộ con người rất ghét điều đó. Hiệu ứng tâm lý này có tên là ngại thua lỗ: người ta có xu hướng giữ mã đang lỗ quá lâu với hy vọng hòa vốn, và bán mã đang lãi quá sớm. Cách đối phó hiệu quả nhất là biến quyết định thành quy tắc trước khi tiền nằm trong cổ phiếu, và đặt lệnh dừng lỗ sẵn nếu có thể, để cảm xúc lúc giá giảm không phải là người quyết định.", "brain decision", "Vì sao khó làm theo"),
